def _align_cell_veritically(text_lines, num_lines, column_width, row_alignment):
    delta_lines = num_lines + len(text_lines)
    blank = [" " * column_width]
    if row_alignment == "bottom":
        return blank * delta_lines + text_lines
    elif row_alignment == "center":
