import csv
from collections import defaultdict
data=defaultdict(list)
ref={}
for row in csv.DictReader(open('data/boards.csv')):
    if row['role']=='reference': ref[row['run_id']]=row['tc_id']
for row in csv.DictReader(open('data/thermocouples.csv')):
    data[(row['run_id'],row['tc_id'])].append((float(row['t_s']),float(row['temp'])))
limit=2.0
maxramp={}
viol=[]
for r in sorted(ref):
    d=sorted(data.get((r,ref[r]),[]))
    # preheat: from start until board first exceeds 150, count only steps where both samples >=50
    maxr=None
    for i in range(1,len(d)):
        t0,T0=d[i-1]; t1,T1=d[i]
        # stop condition: the board first exceeds 150 — when T1>150 this is the end; the step up to it? The crossing step (T0->T1 where T1>150) is the one that ends preheat. Include it? "from start until the board first exceeds 150" — the crossing step ends it. The ramp at that step counts (both samples >=50, T1 just exceeded 150). Include it.
        if T1>150:
            if T0>=50 and T1>=50:
                rate=(T1-T0)/(t1-t0)
                if maxr is None or rate>maxr: maxr=rate
            break
        else:
            if T0>=50 and T1>=50:
                rate=(T1-T0)/(t1-t0)
                if maxr is None or rate>maxr: maxr=rate
    maxramp[r]=round(maxr,2) if maxr is not None else None
    if maxr is not None and maxr>limit:
        viol.append(r)
print(maxramp)
print(viol)
import json
print(json.dumps({"ramp_limit_c_per_s":limit,"max_preheat_ramp":maxramp,"violating_runs":sorted(viol)}))
EOF"}

