import csv
from datetime import datetime, time

# Day shift 2026-09-12: 06:00 to 14:00
with open('/app/data/sensor_log.csv') as f:
    r = csv.DictReader(f)
    # track per machine consecutive DOWN runs within day shift window
    start = datetime(2026,9,12,6,0)
    end = datetime(2026,9,12,14,0)
    # We need contiguous DOWN segments; each row is 1 minute
    cur_state = {}
    seg_start = {}
    downtime = {'M01':0,'M02':0,'M03':0}
    for row in r:
        ts = datetime.strptime(row['timestamp'], '%Y-%m-%d %H:%M')
        if ts < start or ts >= end:
            # outside window; reset segment? If a DOWN segment spans into window, we only count within window.
            # We'll treat segments independently: reset when leaving window
            cur_state[row['machine_id']] = None
            continue
        mid = row['machine_id']
        state = row['state']
        if state == 'DOWN':
            if cur_state.get(mid) == 'DOWN' and mid in seg_start:
                pass  # continue segment
            else:
                seg_start[mid] = ts
                cur_state[mid] = 'DOWN'
        else:
            if cur_state.get(mid) == 'DOWN' and mid in seg_start:
                # segment ended at ts (this row is the first non-DOWN)
                seg_end = ts
                dur = (seg_end - seg_start[mid]).total_seconds()/60
                if dur >= 5:  # exclude micro-stops <5 min
                    downtime[mid] += dur
            cur_state[mid] = state
            seg_start.pop(mid, None)
    print(downtime)

