import csv

# Load data
orders = []
with open('/app/data/orders.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        orders.append(row)

with open('/app/data/vans.json') as f:
    config = json.load(f)

depot = config['depot']
speed = config['speed_kmh']
service_min = config['service_minutes_per_stop']
# Departure time
from datetime import datetime
depart = datetime.strptime(config['departure'], '%H:%M')
depart_minutes = depart.hour * 60 + depart.minute

capacities = {van: cfg['capacity_kg'] for van, cfg in config['vans'].items()}
vans = list(capacities.keys())

def haversine_km(lat1, lon1, lat2, lon2):
    R = 6371.0
    phi1 = math.radians(lat1)
    phi2 = math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dl = math.radians(lon2 - lon1)
    a = math.sin(dphi/2)**2 + math.cos(phi1)*math.cos(phi2)*math.sin(dl/2)**2
    c = 2*math.asin(math.sqrt(a))
    return R * c

# Cancelled order: C06
# Road works: no direct drive between C05 and C08

candidates = [o for o in orders if o['order_id'] != 'C06']

dist = {}
for o1 in candidates:
    for o2 in candidates:
        if o1['order_id'] != o2['order_id']:
            dist[(o1['order_id'], o2['order_id'])] = haversine_km(
                float(o1['lat']), float(o1['lon']), float(o2['lat']), float(o2['lon']))

for o in candidates:
    dist[('depot', o['order_id'])] = haversine_km(
        float(depot['lat']), float(depot['lon']), float(o['lat']), float(o['lon']))
    dist[(o['order_id'], 'depot')] = haversine_km(
        float(o['lat']), float(o['lon']), float(depot['lat']), float(depot['lon']))

def to_minutes(tstr):
    h, m = map(int, tstr.split(':'))
    return h*60 + m

windows = {}
for o in candidates:
    windows[o['order_id']] = (to_minutes(o['window_start']), to_minutes(o['window_end']))

def check_route(route):
    """Return (feasible, total_km, end_time_minutes)."""
    total_km = 0.0
    t = depart_minutes  # departure time
    for i, oid in enumerate(route):
        prev = 'depot' if i == 0 else route[i-1]
        d = dist[(prev, oid)]
        travel_min = d / speed * 60.0
        t += travel_min
        total_km += d
        wstart, wend = windows[oid]
        if t > wend + 1e-9:
            return False, total_km, t
        # wait until window opens (t already includes travel; if before window, wait)
        if t < wstart:
            t = wstart
        t += service_min
    # return to depot
    total_km += dist[(route[-1], 'depot')]
    return True, total_km, t

def is_direct_edge(a, b):
    # Check road works between C05 and C08
    if {a, b} == {'C05', 'C08'}:
        return True
    return False

def valid_route(route):
    for i in range(len(route)-1):
        if is_direct_edge(route[i], route[i+1]):
            return False
    return True

import itertools

best = None

# Enumerate all partitions of candidates into two ordered routes for the two vans.
# For each van, consider all permutations of a subset.
ids = [o['order_id'] for o in candidates]

# Precompute valid permutations and their (km) for each subset per van
# Number of orders = 7. 2^7 = 128 subsets, total permutations sum = 1 + 7 + 42 + 168 + 504 + 1050 + 1470 + 1260 = 4502 per van. Manageable.

def perms_valid(subset_ids):
    for perm in itertools.permutations(subset_ids):
        if valid_route(list(perm)):
            feasible, km, _ = check_route(list(perm))
            if feasible:
                yield list(perm), km

# For V1 choose subset S, V2 gets complement. Both non-overlapping.
from collections import defaultdict

routes_V1 = defaultdict(list)
routes_V2 = defaultdict(list)

for r, km in perms_valid(ids):
    routes_V1[tuple(r)].append(km)
# But we need per-subset. Let's restructure: iterate subsets for V1.

import math
def all_subsets(n):
    return [list(s) for r in range(0, n+1) for s in itertools.combinations(range(n), r)]

best_total = float('inf')
best_plan = None

# Build per-van feasible route table keyed by frozenset of ids -> (km)
# Since both vans identical constraints except assignment, compute per van.

def feasible_routes_for(van_ids):
    table = {}
    for r in range(0, len(van_ids)+1):
        for subset in itertools.combinations(van_ids, r):
            for perm, km in perms_valid(list(subset)):
                key = frozenset(subset)
                if key not in table or km < table[key]:
                    table[key] = km
    return table

# But perms_valid yields only feasible ones; we want min km per subset.

def min_km_for_subsets(van_ids):
    best_per_subset = {}
    for r in range(0, len(van_ids)+1):
        for subset in itertools.combinations(van_ids, r):
            minkm = None
            for perm, km in perms_valid(list(subset)):
                if minkm is None or km < minkm:
                    minkm = km
            key = frozenset(subset)
            if minkm is not None:
                best_per_subset[key] = minkm
    return best_per_subset

cands = ids
v1table = min_km_for_subsets(cands)
v2table = min_km_for_subsets(cands)

full = frozenset(cands)
for v1set, km1 in v1table.items():
    v2set = full - v1set
    if v2set in v2table:
        total = km1 + v2table[v2set]
        if total < best_total:
            best_total = total
            # Need actual routes for the plan
            # Find best route for v1set and v2set
            v1route = None; v1km = None
            for perm, km in perms_valid(list(v1set)):
                if v1km is None or km < v1km:
                    v1km = km; v1route = perm
            v2route = None; v2km = None
            for perm, km in perms_valid(list(v2set)):
                if v2km is None or km < v2km:
                    v2km = km; v2route = perm
            best_plan = (v1route, v2route, total)

v1route, v2route, total = best_plan
plan = {
    "routes": {"V1": v1route, "V2": v2route},
    "total_km": round(total, 2)
}

import os
os.makedirs('/app/output', exist_ok=True)
with open('/app/output/plan.json', 'w') as f:
    json.dump(plan, f, indent=2)
print(json.dumps(plan, indent=2))
print("total km:", total)
